import pytest
from candidate import sort_numbers


class TestSortNumbers:
    def test_single_number(self):
        assert sort_numbers('three') == 'three'

    def test_two_numbers_out_of_order(self):
        assert sort_numbers('five one') == 'one five'

    def test_three_numbers_shuffled(self):
        assert sort_numbers('three one five') == 'one three five'

    def test_all_numbers_shuffled(self):
        assert sort_numbers('nine eight seven six five four three two one zero') == 'zero one two three four five six seven eight nine'

    def test_all_numbers_in_order(self):
        assert sort_numbers('zero one two three four five six seven eight nine') == 'zero one two three four five six seven eight nine'

    def test_duplicates(self):
        assert sort_numbers('five five one') == 'one five five'

    def test_zero_and_nine(self):
        assert sort_numbers('nine zero') == 'zero nine'

    def test_empty_string(self):
        assert sort_numbers('') == ''

    def test_single_space(self):
        assert sort_numbers(' ') == ''

    def test_multiple_spaces_between_numbers(self):
        assert sort_numbers('one  five') == 'one five'

    def test_leading_trailing_spaces(self):
        assert sort_numbers('  one three  ') == 'one three'

    def test_consecutive_spaces(self):
        assert sort_numbers('one   two   three') == 'one two three'

    def test_none_input_raises_error(self):
        with pytest.raises(AttributeError):
            sort_numbers(None)

    def test_invalid_word_raises_key_error(self):
        with pytest.raises(KeyError):
            sort_numbers('hello one')

    def test_integer_input_raises_error(self):
        with pytest.raises(AttributeError):
            sort_numbers(123)

    def test_list_input_raises_error(self):
        with pytest.raises(AttributeError):
            sort_numbers(['one', 'two'])

    def test_uppercase_word_raises_key_error(self):
        with pytest.raises(KeyError):
            sort_numbers('One')

    def test_adjacent_numbers_zero_one(self):
        assert sort_numbers('one zero') == 'zero one'

    def test_adjacent_numbers_eight_nine(self):
        assert sort_numbers('nine eight') == 'eight nine'

    def test_mixed_adjacent_and_nonadjacent(self):
        assert sort_numbers('seven two nine four') == 'two four seven nine'

    def test_all_same_number(self):
        assert sort_numbers('four four four four') == 'four four four four'

    def test_zero_only(self):
        assert sort_numbers('zero') == 'zero'

    def test_nine_only(self):
        assert sort_numbers('nine') == 'nine'

    def test_returns_string_type(self):
        result = sort_numbers('one two')
        assert isinstance(result, str)

    def test_no_trailing_space_in_output(self):
        result = sort_numbers('two one')
        assert result == 'one two'
        assert not result.endswith(' ')

    def test_no_leading_space_in_output(self):
        result = sort_numbers('two one')
        assert not result.startswith(' ')

    def test_tab_separated_input_splits_on_space_only(self):
        with pytest.raises(KeyError):
            sort_numbers('one\ttwo')

    def test_newline_separated_input(self):
        with pytest.raises(KeyError):
            sort_numbers('one\ntwo')

    def test_mixed_valid_and_invalid_raises(self):
        with pytest.raises(KeyError):
            sort_numbers('one invalid three')

    def test_numbers_already_sorted_smallest_to_largest(self):
        assert sort_numbers('zero one two three four five six seven eight nine') == 'zero one two three four five six seven eight nine'

    def test_numbers_sorted_largest_to_smallest(self):
        assert sort_numbers('nine eight seven six five four three two one zero') == 'zero one two three four five six seven eight nine'
